    <label className="flex items-center gap-3 rounded-xl border-l-0 px-3 py-2.5 hover:bg-muted/60 sm:border-l sm:border-border"><Building2 size={18} className="text-secondary" /><span className="sr-only">Property type</span><select value={type} onChange={(e) => setType(e.target.value)} className="w-full bg-transparent text-sm font-semibold outline-none sm:w-40" data-testid="select-search-type"><option value="">Any home type</option><option>Apartment</option><option>House</option><option>Studio</option></select></label>
