    <section className="mx-auto max-w-7xl px-5 py-20 lg:px-8"><div className="grid gap-8 rounded-[2rem] bg-accent px-7 py-9 md:grid-cols-[1fr_auto] md:items-center md:px-12"><div><p className="font-mono-brand text-[10px] uppercase tracking-[.2em] text-ink/60">For people with keys</p><h2 className="mt-2 font-display text-3xl tracking-[-.035em] text-ink">Have a home to share?</h2><p className="mt-2 max-w-xl text-sm text-ink/65">Reach serious long-term tenants and keep your numbers simple. RentFaster takes 10% and pays you the rest.</p></div><Link href="/landlord/new" className="flex items-center justify-center gap-2 rounded-full bg-ink px-5 py-3 text-sm font-bold text-cream transition-transform hover:-translate-y-0.5" data-testid="link-list-property">List your property <ArrowRight size={16} /></Link></div></section>
